// Auto-generated sample frame PNG (base64) used only by the demo harness.
/* eslint-disable */
const BASE64 =
  '';

function decode(): Uint8Array {
  const bin = atob(BASE64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

export const SAMPLE_FRAME_BYTES = decode();
export const SAMPLE_FRAME_WIDTH = 1200;
export const SAMPLE_FRAME_HEIGHT = 800;
